
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ityh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ityh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.204635725913922e+00, -4.122695099587911e+00, -4.007946963858235e+00, -3.849137901749415e+00, -3.633039658143436e+00, -3.346036272762179e+00, -2.977826281391216e+00, -2.527932944792215e+00, -2.013820571515614e+00, -1.472963568040818e+00, -9.475265242684919e-01, -5.945759751794241e-01, -4.953487525126773e-01, -3.902200472550630e-01, -2.508502226988233e-01, -1.149798877640727e-01, -2.375837752676246e-02, -1.103309880372187e-03, -1.077436401354174e-05, -1.503210863010867e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


